UPDATE item_instances SET rolled_stats = json_set(rolled_stats, '$.hpRegen', (SELECT MAX(1, CAST(ROUND(((json_extract(m.stats,'$.hpRegen[0]') + (json_extract(m.stats,'$.hpRegen[1]') - json_extract(m.stats,'$.hpRegen[0]')) * ((abs(random()) % 10001) / 10000.0)) * (CASE substr(item_type,15,1) WHEN '1' THEN 1.0 WHEN '2' THEN 1.25 WHEN '3' THEN 1.6 ELSE 2.2 END))) AS INTEGER)) FROM equipment_master m WHERE m.item_key = 'belt.u.' || substr(item_type,11,1) || '.' || substr(item_type,13,1)))
  WHERE item_type LIKE 'eq.belt.u.%' AND rolled_stats IS NOT NULL AND json_extract(rolled_stats, '$.hpRegen') IS NULL
    AND EXISTS (SELECT 1 FROM equipment_master m WHERE m.item_key = 'belt.u.' || substr(item_type,11,1) || '.' || substr(item_type,13,1) AND json_extract(m.stats, '$.hpRegen') IS NOT NULL);
UPDATE item_instances SET rolled_stats = json_set(rolled_stats, '$.mpRegen', (SELECT MAX(1, CAST(ROUND(((json_extract(m.stats,'$.mpRegen[0]') + (json_extract(m.stats,'$.mpRegen[1]') - json_extract(m.stats,'$.mpRegen[0]')) * ((abs(random()) % 10001) / 10000.0)) * (CASE substr(item_type,15,1) WHEN '1' THEN 1.0 WHEN '2' THEN 1.25 WHEN '3' THEN 1.6 ELSE 2.2 END))) AS INTEGER)) FROM equipment_master m WHERE m.item_key = 'ring.u.' || substr(item_type,11,1) || '.' || substr(item_type,13,1)))
  WHERE item_type LIKE 'eq.ring.u.%' AND rolled_stats IS NOT NULL AND json_extract(rolled_stats, '$.mpRegen') IS NULL
    AND EXISTS (SELECT 1 FROM equipment_master m WHERE m.item_key = 'ring.u.' || substr(item_type,11,1) || '.' || substr(item_type,13,1) AND json_extract(m.stats, '$.mpRegen') IS NOT NULL);
