  WHERE item_type LIKE 'eq.necklace.m.%' AND rolled_stats IS NOT NULL AND json_extract(rolled_stats, '$.hpRegenPct') IS NULL
    AND EXISTS (SELECT 1 FROM equipment_master m WHERE m.item_key = 'necklace.m.' || substr(item_type,15,1) || '.' || substr(item_type,17,1) AND json_extract(m.stats, '$.hpRegenPct') IS NOT NULL);
